--
-- Table structure for table `inventory_stocks`
--

DROP TABLE IF EXISTS `inventory_stocks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `inventory_stocks` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `inventory_item_id` bigint unsigned NOT NULL,
  `received_date` date NOT NULL,
  `quantity_received` decimal(12,2) NOT NULL DEFAULT '0.00',
  `quantity_remaining` decimal(12,2) NOT NULL DEFAULT '0.00',
  `usable_life_value` int unsigned NOT NULL DEFAULT '1',
  `usable_life_unit` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'days',
  `usable_until` date NOT NULL,
  `unit_cost` decimal(12,2) DEFAULT NULL,
  `created_by` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `inventory_stocks_inventory_item_id_foreign` (`inventory_item_id`),
  KEY `inventory_stocks_created_by_foreign` (`created_by`),
  KEY `inventory_stocks_usable_until_index` (`usable_until`),
  CONSTRAINT `inventory_stocks_created_by_foreign` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `inventory_stocks_inventory_item_id_foreign` FOREIGN KEY (`inventory_item_id`) REFERENCES `inventory_items` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=271 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

