INSERT INTO `packages` VALUES (1,'CGW','Classic Garden Wedding','Wedding','A classic garden wedding decoration package featuring fresh roses, baby\'s breath, eucalyptus foliage, hydrangeas, elegant glass vases, floral accents, and wooden flower stands. Designed for intimate to medium-sized wedding celebrations.',45000.00,'[\"50 Red Roses\", \"30 White Roses\", \"10 Baby\'s Breath Bunches\", \"10 Eucalyptus Bunches\", \"8 Hydrangea Stems\", \"6 Medium Glass Vases\", \"4 White Satin Ribbon Rolls\", \"2 Wooden Flower Stands\", \"8 Floral Foam Blocks\", \"4 Pampas Grass Bunches\"]',NULL,1,'2026-10-06 02:51:20','2026-10-06 02:51:20',0),(2,'EBC','Elegant Birthday Celebration','Birthday','A stylish birthday celebration package featuring fresh roses, sunflowers, baby\'s breath, decorative foliage, glass vases, satin ribbons, and elegant floral accents for a memorable birthday event.',30000.00,'[\"30 Red Roses\", \"20 White Roses\", \"15 Sunflowers\", \"6 Baby\'s Breath Bunches\", \"5 Eucalyptus Bunches\", \"4 Medium Glass Vases\", \"2 White Satin Ribbon Rolls\", \"4 Floral Foam Blocks\", \"2 Pampas Grass Bunches\"]',NULL,1,'2026-10-06 02:56:43','2026-10-06 02:56:43',0),(3,'CFS','Corporate Floral Setup','Corporate Event','Professional floral decoration package designed for corporate events, seminars, conferences, and business gatherings. Includes elegant floral arrangements, foliage, preserved accents, vases, and reusable display stands.',25000.00,'[\"20 White Roses\", \"15 Sunflowers\", \"8 Eucalyptus Bunches\", \"5 Preserved Fern Bunches\", \"6 Medium Glass Vases\", \"4 Floral Foam Blocks\", \"2 Wooden Flower Stands\", \"2 White Satin Ribbon Rolls\"]',NULL,1,'2026-10-06 02:59:56','2026-10-06 02:59:56',0),(4,'CWP','Classic Wedding Package','Wedding','Elegant floral setup for bridal and entourage',25000.00,'[\"Bridal bouquet\", \"Groom boutonniere\", \"3 Bridesmaid bouquets\", \"5 Boutonnieres\"]',NULL,1,'2026-10-09 01:32:46','2026-10-09 01:32:46',0),(8,'PKG-WED-01','Grand Garden Wedding Arch Suite','Wedding','Comprehensive wedding floral package including ceremony arch and aisle stands.',25000.00,'[\"1x Arch Frame (Metal)\", \"40x Red Roses\", \"20x White Roses\", \"2x Metal Floral Stand\", \"4x Tall Glass Vases\", \"5x Eucalyptus Foliage bunches\"]',NULL,1,'2026-08-10 05:49:09','2026-08-10 05:49:09',0),(9,'PKG-DEB-01','Pastel Debutante Floral Table Suite','Debut','Soft pastel tablescape package with delicate roses and baby breath.',15000.00,'[\"24x Pink Roses\", \"24x White Roses\", \"10x Baby\'s Breath bunches\", \"6x Tall Glass Vases\"]',NULL,1,'2026-08-20 05:49:09','2026-08-20 05:49:09',0),(10,'PKG-CORP-01','Executive Corporate Gala Centerpieces','Corporate','Modern minimalist corporate centerpieces for conference and gala tables.',12000.00,'[\"30x White Roses\", \"6x Tall Glass Vases\", \"6x Eucalyptus Foliage bunches\"]',NULL,1,'2026-08-30 05:49:09','2026-08-30 05:49:09',0);
